"css": "\n/* ³⁹ 題字の左にアイコン（DB の行ページ）— アイコンを題名の上ではなく左に並べる。書体は Atelier に任せ、並びだけを変える */\n:root{ --c39-ticon-gap: 10px; --c39-ticon-y: 0px; }\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]){\n  display:flex !important; flex-wrap:wrap !important; align-items:center !important; column-gap:var(--c39-ticon-gap) !important; row-gap:0 !important;\n}\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]) > *{ flex:0 0 100%; min-width:0; }\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]) > div:has(> .notion-record-icon[aria-label=\"Change page icon\"]){\n  flex:0 0 auto !important; display:flex !important; align-items:center !important; margin:0 !important; padding:0 !important;\n}\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]) > div:has(> .notion-record-icon[aria-label=\"Change page icon\"]) > .notion-record-icon{\n  margin:0 0 0 8px !important; transform:translateY(var(--c39-ticon-y)) !important;\n}\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]) > div:has(> .notion-page-block > h1[aria-roledescription=\"page title\"]){\n  flex:1 1 0% !important; min-width:0 !important;\n}\n.layout:has([aria-label=\"View/hide details\"]) div:has(> div > .notion-record-icon[aria-label=\"Change page icon\"]):has(> div > .notion-page-block > h1[aria-roledescription=\"page title\"]) > div:has(> .notion-page-block > h1) h1[aria-roledescription=\"page title\"]{\n  padding-inline-start:0 !important;\n}\n",
"from": "新規",
